import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Effective-Weight.md","filePath":"manual-en/CTABLES-Effective-Weight.md","lastUpdated":1785684581000}'),n={name:"manual-en/CTABLES-Effective-Weight.md"};function c(r,e,s,d,f,h){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h4 id="_15-7-11-effective-weight" tabindex="-1">15.7.11 Effective Weight <a class="header-anchor" href="#_15-7-11-effective-weight" aria-label="Permalink to &quot;15.7.11 Effective Weight&quot;">​</a></h4><pre><code>/WEIGHT VARIABLE=_variable_
</code></pre><p>The <code>WEIGHT</code> subcommand is optional and must appear before <code>TABLE</code>. If it appears, it must name a numeric variable, known as the <em>effective weight</em> or <em>adjustment weight</em>. The effective weight variable stands in for the dictionary’s weight variable (see <a href="./WEIGHT">WEIGHT</a>), if any, in most calculations in <code>CTABLES</code>. The only exceptions are the <code>COUNT</code>, <code>TOTALN</code>, and <code>VALIDN</code> summary functions, which use the dictionary weight instead.</p><p>Weights obtained from the PSPP dictionary are rounded to the nearest integer at the case level. Effective weights are not rounded. Regardless of the weighting source, PSPP does not analyze cases with zero, missing, or negative effective weights.</p>`,4)])])}const _=t(n,[["render",c]]);export{m as __pageData,_ as default};
